#include "KS/SRC/ks/FEMenu_shared.h"
#include "KS/SRC/ks/igo_widget_shared.h"

struct MemCard {
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class FEManager {
    char padding[0x15678];
public:
    bool fe_done;
};

class SoundScriptManager {
public:
    enum EventType { SS_FE_LEFTRIGHT = 26 };
    static SoundScriptManager *inst();
    void pause();
    void unpause();
    void playEvent(EventType type, void *entity = 0, float value = 0.0f);
};

class NamesMenu : public FEMultiMenu {
    static const int arrow_timer = 3;
    char padding0[0x178 - sizeof(FEMultiMenu)];
    int arrow_num;
    int arrow_counter;
    char padding1[0x1bc - 0x180];
    MemCard cards[2];
    char padding2[0x200 - 0x1f4];
    int adjusted_active_card;
    char padding3[0x20c - 0x204];
    PanelQuad *arrows[2][2];
public:
    void OnRight(int c);
private:
    void OnCardSwitch();
    void MakeSpaceFreeMessage(int free);
};

extern FEManager frontendmanager;
extern SoundScriptManager *sound_script_manager;

__asm__(".equ frontendmanager, 0x003F7728");
__asm__(".equ sound_script_manager, 0x0045B4A0");
__asm__(".equ OnCardSwitch__9NamesMenu, 0x0019F9D8");
__asm__(".equ MakeSpaceFreeMessage__9NamesMenui, 0x0019E790");
__asm__(".equ unpause__18SoundScriptManager, 0x0031BFA8");
__asm__(".equ pause__18SoundScriptManager, 0x0031BF98");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf, 0x0031C380");

SoundScriptManager *SoundScriptManager::inst()
{
    return sound_script_manager;
}

void NamesMenu::OnRight(int c)
{
	FEMenuEntry* initial = highlighted;
	FEMenuEntry* before = highlighted;
	FEMultiMenu::OnRight(c);
	if(before != highlighted)
	{
		OnCardSwitch();
	}
	if(initial != highlighted)
	{
		if (frontendmanager.fe_done)
			SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_LEFTRIGHT);
		if (frontendmanager.fe_done)
			SoundScriptManager::inst()->pause();
		arrows[1][1]->TurnOn(true);
		arrows[1][0]->TurnOn(false);
		arrow_num = 1;
		arrow_counter = arrow_timer;
		cards[adjusted_active_card].changed = true;
		MakeSpaceFreeMessage(cards[adjusted_active_card].free);
	}
}
